package io.github.ningpp.compat;

/**
 * Holder for ref/out object parameters (generated by CSharpToJava converter).
 *
 * <p>Extends {@link ByRef} so a cross-project call site (whose ref/out lowering
 * emits a fresh {@code ObjectHolder}) remains assignable to a callee whose
 * declaration project lowered the same parameter to {@code ByRef<T>} — the two
 * projections must stay ABI-compatible (real chain: dotnet-xml XmlConvert calls
 * the dotnet-uri Uri.TryCreate(string, UriKind, out Uri) declaration).</p>
 */
public final class ObjectHolder<T> extends ByRef<T> {
    public T value;
    public ObjectHolder() { this.value = null; }
    public ObjectHolder(T value) { this.value = value; }

    @Override public T getValue() { return value; }
    @Override public T setValue(T value) { this.value = value; return value; }
}
